<script setup lang="ts">
import type {ClientNotification} from '~/types/booking'
import {collectionItems} from '~/composables/useBackend'
const api=useBookingApi(),{ensure}=usePrivatePage(),{t,path,formatDate}=useSiteLocale()
const items=ref<ClientNotification[]>([]),loading=ref(true),busy=ref(0),error=ref('')
const unread=computed(()=>items.value.filter(item=>!item.read_at).length)
useSeoMeta({title:'اعلان‌های من',robots:'noindex,nofollow'})
async function load(){loading.value=true;error.value='';try{items.value=collectionItems<ClientNotification>(await api.notifications())}catch(e){error.value=bookingMessage(e,t)}finally{loading.value=false}}
onMounted(async()=>{if(await ensure())await load();else loading.value=false})
async function markRead(item:ClientNotification){if(item.read_at||busy.value)return;busy.value=item.id;error.value='';try{await api.readNotification(item.id);items.value=items.value.map(entry=>entry.id===item.id?{...entry,read_at:new Date().toISOString()}:entry)}catch(e){error.value=bookingMessage(e,t)}finally{busy.value=0}}
</script>
<template><section class="account-notifications-page"><div class="section-title"><div><h1>اعلان‌ها</h1><p class="muted">{{unread?`${unread} اعلان خوانده‌نشده`: 'همه اعلان‌ها خوانده شده‌اند'}}</p></div><button class="btn secondary notification-refresh" type="button" :disabled="loading" @click="load">تازه‌سازی</button></div><p v-if="loading">در حال دریافت اعلان‌ها…</p><ApiNotice v-if="error">{{error}}</ApiNotice><template v-else-if="items.length"><div class="table-wrap notification-table-wrap"><table class="data-table notification-table"><caption class="sr-only">فهرست اعلان‌ها</caption><thead><tr><th scope="col">عنوان</th><th scope="col">توضیحات</th><th scope="col">وضعیت</th><th scope="col">تاریخ</th><th scope="col">اقدام</th></tr></thead><tbody><tr v-for="item in items" :key="item.id" :class="{'notification-row-unread':!item.read_at}"><th scope="row">{{item.title}}</th><td class="notification-description">{{item.body}}</td><td><span class="status-pill" :data-status="item.read_at?'read':'pending'">{{item.read_at?'خوانده‌شده':'خوانده‌نشده'}}</span></td><td>{{formatDate(item.created_at)}}</td><td><div class="notification-table-actions"><NuxtLink v-if="item.booking_id" class="more" :to="path(`/account/appointments/${item.booking_id}`)">جزئیات نوبت</NuxtLink><button v-if="!item.read_at" class="notification-read-button" type="button" :disabled="busy===item.id" @click="markRead(item)">{{busy===item.id?'در حال ثبت…':'خوانده شد'}}</button></div></td></tr></tbody></table></div><div class="table-mobile notification-mobile-list"><article v-for="item in items" :key="`mobile-${item.id}`" class="payment-card notification-card" :class="{'notification-row-unread':!item.read_at}"><div class="payment-card-heading"><strong>{{item.title}}</strong><span class="status-pill" :data-status="item.read_at?'read':'pending'">{{item.read_at?'خوانده‌شده':'خوانده‌نشده'}}</span></div><p>{{item.body}}</p><p>{{formatDate(item.created_at)}}</p><div class="account-actions notification-mobile-actions"><NuxtLink v-if="item.booking_id" class="btn secondary" :to="path(`/account/appointments/${item.booking_id}`)">جزئیات</NuxtLink><button v-if="!item.read_at" class="btn" type="button" :disabled="busy===item.id" @click="markRead(item)">{{busy===item.id?'در حال ثبت…':'خوانده شد'}}</button></div></article></div></template><ApiNotice v-else-if="!loading">اعلانی برای نمایش ندارید.</ApiNotice></section></template>
